def decimal_number_to_fraction_str(decimal_number: float) -> str:
    """ Given a positive floating point decimal number, it returns
    the fraction as string, for instance 1.0 will become '1.0'.
    """
    number_str = '{0:g}'.format(decimal_number)
    number_str_no_commas = ''.join(filter(lambda c: c!='.', number_str))
    return '{0}/{1}'.format(decimal_number, number_str_no_commas)


