def calculate_parenthesis_depth(parenthesis_string: str) -> int:
    """ This function counts the levels of nesting of the parenthesis in a given parenthesis_string.
    E.g. "(()(()))" has three levels of nesting.
    >>> calculate_parenthesis_depth("(()(()))")
    3
    >>> calculate_parenthesis_depth("(())")
    1
    """
    nesting_count = 0
    for char in parenthesis_string:
        if char == '(':
            nesting_count += 1
        elif char == ')':
            nesting_count -= 1
        if nesting_count < 0:
            raise Exception("Invalid Parenthesis")
    return nesting_count


