        open_brac_count, close_brac_count = 0, 0
        for index, value in enumerate(paren_string[start:]):
            if value == '(':
                open_brac_count += 1
            elif value == ')':
                close_brac_count += 1
            if open_brac_count < close_brac_count:
                return close_brac_count
        return close_brac_count

    count = check_balance(paren_string, 0)
    if count < len(paren_string):
        count = check_balance(paren_string, count)
    if count == len(paren_string):
