def parenthetical_depth(paren_string: str) -> int:
    """ Input to this function is a string containing multiple nested parenthesized strings. Your goal is to
    find and return the largest distance between outermost parentheses.
    For instance, if the string is '(((()())())())', the string is nested 4 layers deep. If string is '()',
    string is nested only 1 layer deep.
    """

    def find_depth(paren_string: str, depth: int) -> int:
        if not paren_string:
            return depth
        elif paren_string[0] == '(':
            return find_depth(paren_string[1:], depth + 1)
        elif paren_string[0] == ')':
            return find_depth(paren_string[1:], depth - 1)
        else:
            return find_depth(paren_string[1:], depth)

    return find_depth(paren_string, 0)


