    """ Check if the parentheses in the string are balanced and well formed.
    Balanced means that each open parenthesis has a corresponding close parenthesis.
    Well formed means that closing parens always occur in the correct order.
    Examples of balanced and well formed parentheses: ()
    Examples of unbalanced: (( ()
    Examples of badly formed: )( Greek thorn )(
    """
    stack = []
    pairs = {")": "(", "}": "{", "]": "["}
    for ch in paren_string:
        if ch in "({[":
            stack.append(ch)
        if ch in ")}]":
            if not stack or stack.pop() != pairs[ch]: return False
    return not stack

