def _get_nested_count_from_char(c: str) -> int:
    open_paren = ['(', '[', '{']
    closed_paren = [')', ']', '}']
    brackets = {'(': ')', '[': ']', '{': '}'}

    count = 0
    bracket_stack = []

    for bracket in c:
        if bracket in open_paren:
            bracket_stack.append(bracket)
            count += 1
        if bracket in closed_paren:
            opened_bracket = bracket_stack.pop()
            if brackets[opened_bracket] != bracket:
                raise Exception('Mismatched brackets!')
            count -= 1

    return count

