def remove_duplicates(nums: List[int]):
    """
    Remove duplicates form list of integers. Resulting list is sorted.
    >>> remove_duplicates([1, 1, 5, 5, 2, 4, 3, 1, 4])
    [1, 2, 3, 4, 5]
    """
    nums2 = nums[:]
    for i in range(len(nums2)):
        index = i
        for j in range(index+1, len(nums2)):
            if nums2[index] > nums2[j]:
                index = j
        nums2[index], nums2[i] = nums2[i], nums2[index]
    index = 0
    while index < len(nums2)-1:
        if nums2[index] == nums2[index+1]:
            del nums2[index+1]
        else:
            index += 1
    return nums2


