def parse_nested_parens_opt(paren_string: str) -> List[int]:
    """ Input to this function is a string represented multiple groups for nested parentheses separated by spaces.
    For each of the group, output the deepest level of nesting of parentheses.
    E.g. (()()) has maximum two levels of nesting while ((())) has three.

    >>> parse_nested_parens_opt('(()()) ((())) () ((())()())')
    [2, 3, 1, 3]
    """
    res = []
    stack = []
    for char in paren_string:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if stack[-1] == '(':
                level = 0
                for top in stack[::-1]:
                    level += 1
                    if top == ')':
                        stack.pop()
                        break
                res.append(level)
            stack.pop()
    return res

    result = []
    for group in paren_string.split(' '):
        count_open, count_close, max_value = 0, 0, 0
        for char in group:
            if char == '(':
                count_open += 1
                max_value = max(max_value, count_close)
            elif char == ')':
                count_close += 1
        result.append(max_value)
    return result


