def filter_by_values(dictionary: dict, value: int) -> dict:
    """ Filter input dictionary only for items with value equals given
    >>> filter_by_values({1: 100, 2: 200, 3: 300, 4: 300}, 300)
    {2: 200, 3: 300, 4: 300}
    """
    res = {key: val for (key, val) in dictionary.items() if val == value}
    return res


